const {docs,attachments}=window.PORTFOLIO;
const main=document.querySelector('main'),nav=document.querySelector('#nav'),side=document.querySelector('#sidebar');
const escapeHTML=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const link=d=>`#/docs/${d.id}`;
const mobile=matchMedia('(max-width:800px)');
function syncMenu(){side.inert=mobile.matches&&!side.classList.contains('open');}
function closeMenu(){side.classList.remove('open');document.querySelector('#menu').setAttribute('aria-expanded','false');syncMenu();}
mobile.addEventListener('change',syncMenu);
document.querySelector('#menu').onclick=()=>{side.classList.toggle('open');document.querySelector('#menu').setAttribute('aria-expanded',side.classList.contains('open'));syncMenu();if(side.classList.contains('open'))side.querySelector('.mobile-close').focus();};document.querySelector('.mobile-close').onclick=()=>{closeMenu();document.querySelector('#menu').focus();};document.addEventListener('keydown',e=>{if(e.key==='Escape'&&side.classList.contains('open')){closeMenu();document.querySelector('#menu').focus();}});
nav.innerHTML='<a href="#/" data-id="home">문서 홈</a>'+['전투 분석','비교·제안','프로젝트'].map(g=>`<div class="nav-label">${g}</div>`+docs.filter(d=>d.group===g).map(d=>`<a href="${link(d)}" data-id="${d.id}"><span>${d.number}</span>${d.title.replace(' 고유 전투 시스템 분석','').replace('프로젝트 스피릿 ','')}</a>`).join('')).join('');
const row=d=>`<a class="doc-row" href="${link(d)}"><span class="row-num">${d.number}</span><div><div class="row-title">${d.title}</div><div class="row-desc">${d.description}</div></div><div class="row-meta"><span class="badge">${d.status}</span><span class="arrow" aria-hidden="true">↗</span></div></a>`;
function render(){const route=location.hash||'#/';const id=route.split('/')[2];const d=docs.find(d=>d.id===id);closeMenu();nav.querySelectorAll('a').forEach(a=>{const active=a.dataset.id===(d?.id||(!id?'home':''));a.classList.toggle('active',active);active?a.setAttribute('aria-current','page'):a.removeAttribute('aria-current');});
 if(!id){document.title='Jnhide — 전투 시스템·캐릭터 기획';document.querySelector('#breadcrumb').textContent='포트폴리오 키우기';main.innerHTML=`<div class="eyebrow">PORTFOLIO / DOCUMENTS</div><h1>전투 시스템·캐릭터 기획</h1><p class="intro">공통 전투 구조에서 게임별 분석과 비교, 시스템·캐릭터 제안까지.<br>‘포트폴리오 키우기’의 기획 문서와 프로젝트 기록입니다.</p><div class="chapter-band"><a href="${link(docs[0])}"><small>01 — 04</small><strong>전투 구조 분석</strong><b>→</b></a><a href="${link(docs[4])}"><small>05 — 07</small><strong>비교와 제안</strong><b>→</b></a><a href="#projects"><small>PROJECTS</small><strong>프로젝트 기록</strong><b>↓</b></a></div><section><div class="section-heading"><h2>기획 문서</h2><span>07 documents</span></div>${docs.filter(d=>!d.type).map(row).join('')}</section><section id="projects" class="projects-section"><div class="section-heading"><h2>프로젝트</h2><span>03 projects</span></div><div class="project-grid">${docs.filter(d=>d.type).map(d=>`<a class="project-card" href="${link(d)}"><small>${d.type}</small><h3>${d.title}</h3><p>${d.description}</p><span class="view">프로젝트 기록 보기 →</span></a>`).join('')}</div></section>`;
 }else if(d){document.title=d.title+' — Jnhide';document.querySelector('#breadcrumb').textContent=d.group+' / '+d.title;main.innerHTML=`<header class="document-head"><div class="eyebrow">${d.type?'PROJECT':'DOCUMENT'} ${d.number}</div><h1>${d.title}</h1><p class="intro">${d.description}</p><div class="doc-info"><span class="badge">${d.status}</span><span>Jnhide</span></div></header><div class="doc-layout"><article class="article">${d.body}</article><aside class="toc" aria-label="이 문서의 목차"><strong>이 문서에서</strong></aside></div><section class="attachments"><h2>첨부 자료</h2><div id="assets"></div></section><nav class="doc-pager" aria-label="이전 다음 문서">${docs.indexOf(d)>0?`<a href="${link(docs[docs.indexOf(d)-1])}">← 이전 문서</a>`:'<a href="#/">← 문서 홈</a>'}${docs.indexOf(d)<docs.length-1?`<a href="${link(docs[docs.indexOf(d)+1])}">다음 문서 →</a>`:'<a href="#/">문서 홈 →</a>'}</nav>`;
 main.querySelectorAll('.article h2').forEach((h,i)=>{h.id='section-'+i;const a=document.createElement('a');a.href='#'+h.id;a.textContent=h.textContent;a.onclick=e=>{e.preventDefault();h.scrollIntoView({behavior:'smooth'});};main.querySelector('.toc').append(a);});const files=attachments.filter(a=>a.document===d.id);document.querySelector('#assets').innerHTML=files.length?files.map(a=>`<a class="attachment" href="${escapeHTML(a.url)}" target="_blank" rel="noopener"><small>${escapeHTML(a.type)}</small>${escapeHTML(a.title)} ↗${a.type==='이미지'?`<img src="${escapeHTML(a.url)}" alt="${escapeHTML(a.title)}" loading="lazy">`:''}</a>`).join(''):'<p class="empty-assets">아직 등록된 첨부 자료가 없습니다.</p>';
 }else{main.innerHTML='<div class="not-found"><h1>문서를 찾을 수 없습니다.</h1><a href="#/">문서 홈으로 돌아가기 →</a></div>';document.title='문서를 찾을 수 없습니다 — Jnhide';}
 window.scrollTo(0,0);
}
window.addEventListener('hashchange',()=>{if(location.hash==='#main'){main.focus();return;}if(location.hash==='#projects'){document.querySelector('#projects')?.scrollIntoView({behavior:'smooth'});return;}render();main.focus({preventScroll:true});});render();
